pub fn getFallback(self: TokenList, allocator: Allocator, kind: ColorFallbackKind) @This() {
            var tokens = TokenList{  };
            _ = &tokens;
            _ = bun.handleOom(tokens.v.ensureTotalCapacity(allocator, self.v.items.len));
            tokens.v.items.len = self.v.items.len;
            var i: usize = 0;
            _ = &i;
            while ((i < self.v.items.len)) : (i = (i + 1)) {
                const old = (&self.v.items[@as(usize, @intCast(i))]);
                var target_item = (&tokens.v.items[@as(usize, @intCast(i))]);
                _ = &target_item;
                target_item.* = (switch (old.*) {
.color => |*color| TokenOrValue{ .color = color.getFallback(allocator, kind) },
.function => |*f| TokenOrValue{ .function = f.getFallback(allocator, kind) },
.@"var" => |*v| TokenOrValue{ .@"var" = v.getFallback(allocator, kind) },
.env => |*e| TokenOrValue{ .env = e.getFallback(allocator, kind) },
else => old.deepClone(allocator),
});
            }
            tokens.v.items.len = self.v.items.len;
            return tokens;
    }

pub fn getFallbacks(self: *TokenList, allocator: Allocator, targets: css.targets.Targets) css.SmallList(Fallbacks,2) {
            var fallbacks = self.getNecessaryFallbacks(targets);
            _ = &fallbacks;
            const lowest_fallback = fallbacks.lowest();
            _ = bun.bits.remove(ColorFallbackKind, (&fallbacks), lowest_fallback);
            var res: css.SmallList(Fallbacks,2) = .{};
            _ = &res;
            if (fallbacks.p3) {
                _ = res.appendAssumeCapacity(.{ ColorFallbackKind.P3.supportsCondition(), self.getFallback(allocator, ColorFallbackKind.P3) });
            }
            if (fallbacks.lab) {
                _ = res.appendAssumeCapacity(.{ ColorFallbackKind.LAB.supportsCondition(), self.getFallback(allocator, ColorFallbackKind.LAB) });
            }
            if ((!lowest_fallback.isEmpty())) {
                var idx: usize = 0;
                _ = &idx;
                while ((idx < self.v.items.len)) : (idx = (idx + 1)) {
                    const token_or_value = (&self.v.items[@as(usize, @intCast(idx))]);
                    switch (token_or_value.*) {
.color => |*color| {
color.* = color.getFallback(allocator, lowest_fallback);
},
.function => |*f| {
f.* = f.getFallback(allocator, lowest_fallback);
},
.@"var" => |*v| {
if (v.fallback) |*fallback| {
                        _ = &fallback;
                        (fallback.*).* = (fallback.*).getFallback(allocator, lowest_fallback);
                    }
},
.env => |*v| {
if (v.fallback) |*fallback| {
                        _ = &fallback;
                        (fallback.*).* = (fallback.*).getFallback(allocator, lowest_fallback);
                    }
},
else => {

},
}
                }
            }
            return res;
    }

pub fn getNecessaryFallbacks(self: TokenList, targets: css.targets.Targets) ColorFallbackKind {
            var fallbacks = ColorFallbackKind{  };
            _ = &fallbacks;
            for (self.v.items) |token_or_value| {
                _ = &token_or_value;
                switch (token_or_value) {
.color => |color| {
_ = bun.bits.insert(ColorFallbackKind, (&fallbacks), color.getPossibleFallbacks(targets));
},
.function => |f| {
_ = bun.bits.insert(ColorFallbackKind, (&fallbacks), f.arguments.getNecessaryFallbacks(targets));
},
.@"var" => |v| {
if (v.fallback) |*fallback| {
                    _ = &fallback;
                    _ = bun.bits.insert(ColorFallbackKind, (&fallbacks), (fallback.*).getNecessaryFallbacks(targets));
                }
},
.env => |v| {
if (v.fallback) |*fallback| {
                    _ = &fallback;
                    _ = bun.bits.insert(ColorFallbackKind, (&fallbacks), (fallback.*).getNecessaryFallbacks(targets));
                }
},
else => {

},
}
            }
            return fallbacks;
    }

